<template><section v-loading="loading"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-tabs v-model="tab"><el-tab-pane label="离职办理记录" name="records"><el-table :data="rows" row-key="id"><el-table-column prop="employee_name" label="员工" width="120"/><el-table-column prop="store_name" label="原门店" min-width="180"/><el-table-column prop="leave_date" label="离职日期" width="120"/><el-table-column prop="leave_type" label="类型" width="90"/><el-table-column label="进度" min-width="170"><template #default="{row}">{{row.status==='completed'?'手续完成':row.status==='blocked'?'待人事核查':row.status==='scheduled'?'已登记，待离职日期':row.stage_name}}</template></el-table-column><el-table-column label="操作" width="110"><template #default="{row}"><el-button link type="primary" @click="detail=row;note=''">查看／办理</el-button></template></el-table-column></el-table><p>离职登记不需要上级审批。人事交接、财务结算等环节只记录后续办理结果。</p></el-tab-pane><el-tab-pane v-if="canManage" label="后续环节配置" name="config"><el-alert title="设置提交后的处理顺序和负责人；不增加上级审批。已登记的员工沿用登记时的环节快照。" type="info" :closable="false"/><div v-for="(n,i) in form.nodes" :key="i" class="node"><div class="node-head"><b>{{i+1}} · 后续处理环节</b><el-button link type="danger" :disabled="form.nodes.length===1" @click="form.nodes.splice(i,1)">移除</el-button></div><el-input v-model="n.name" maxlength="40" placeholder="例如：人事交接、财务结算"/><div class="controls"><el-select v-model="n.kind" @change="n.ids=[]"><el-option value="users" label="指定处理人员"/><el-option value="positions" label="按负责门店的岗位匹配"/></el-select><el-select v-model="n.ids" multiple filterable placeholder="选择处理人或岗位"><el-option v-for="p in n.kind==='users'?config.users:config.positions" :key="p.id" :value="p.id" :label="p.name"/></el-select></div><p>本环节任一有效处理人填写结果后，通知下一环节。</p></div><div class="controls"><el-button :disabled="form.nodes.length>=8" @click="form.nodes.push({name:'',kind:'users',ids:[]})">添加环节</el-button><el-button type="primary" :loading="busy" @click="save">保存后续处理配置</el-button></div><p>网页处理人需要开放“离职交接记录查看与本人环节办理”权限；小程序处理人可从消息中心进入。仅需登记的店长使用小程序离职登记权限，不需员工 C/D 编辑权限。</p></el-tab-pane></el-tabs><el-drawer :model-value="!!detail" @close="detail=null" title="离职交接办理" size="640px"><template v-if="detail"><h2>{{detail.employee_name}} · {{detail.leave_type}}</h2><p>{{detail.store_name}} · 离职日期 {{detail.leave_date}}</p><div class="reason">{{detail.reason}}</div><el-timeline><el-timeline-item v-for="(n,i) in detail.nodes" :key="i" :type="n.done?'success':i===detail.stage?'warning':'info'"><b>{{n.name}}</b> · {{n.done?'已完成':i===detail.stage?'待办理':'后续环节'}}<p>{{n.people.map(p=>p.name).join('、')}}</p></el-timeline-item></el-timeline><div v-for="s in detail.steps" :key="s.id" class="result"><b>{{s.name}}</b> · {{s.display_name}}<p>{{s.note}}</p><p>{{time(s.created_at)}}</p></div><template v-if="detail.can_handle"><el-input v-model="note" type="textarea" :rows="4" maxlength="1000" placeholder="填写本环节办理结果，不是上级审批意见"/><el-button class="complete" type="primary" :disabled="!note.trim()" :loading="busy" @click="complete">完成当前处理环节</el-button></template></template></el-drawer></section></template>
<script setup>
import {ref,onMounted,computed} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {useAuthStore} from '@/stores/auth';import {storeOperationsApi as api} from '@/api'
const auth=useAuthStore(),canManage=computed(()=>(auth.user?.position_permissions||[]).some(p=>p==='*'||p==='workflow.manage')),rows=ref([]),config=ref({users:[],positions:[]}),form=ref({revision:0,nodes:[]}),loading=ref(false),busy=ref(false),error=ref(''),tab=ref('records'),detail=ref(null),note=ref(''),time=v=>new Date(v).toLocaleString('zh-CN',{hour12:false})
async function load(){loading.value=true;try{rows.value=(await api.offboardingRecords()).rows;if(canManage.value){config.value=await api.offboardingConfig();form.value={revision:config.value.revision,nodes:config.value.nodes.length?JSON.parse(JSON.stringify(config.value.nodes)):[{name:'人事交接',kind:'users',ids:[]},{name:'财务结算',kind:'users',ids:[]}]};if(!config.value.nodes.length)tab.value='config'}error.value=''}catch(e){error.value=e.message}finally{loading.value=false}}
async function save(){if(busy.value)return;busy.value=true;try{await api.saveOffboardingConfig(form.value);await load();ElMessage.success('后续处理环节已配置')}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function complete(){if(busy.value||!note.value.trim())return;try{await ElMessageBox.confirm('保存本环节办理结果并通知下一环节，不执行付款操作。','完成当前处理');busy.value=true;detail.value=(await api.completeOffboarding(detail.value.id,{revision:detail.value.revision,note:note.value})).record;note.value='';await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'操作失败')}finally{busy.value=false}}
onMounted(load)
</script><style scoped>.node{padding:18px;border:1px solid #e4e9ed;border-radius:12px;margin:18px 0}.node-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.controls{display:flex;gap:12px;align-items:center;margin-top:12px}.controls>.el-select:first-child{width:240px}.controls>.el-select:last-child{flex:1}p{font-size:12px;color:#8796a1;line-height:1.8}.reason{font-size:14px;line-height:1.8;white-space:pre-wrap;margin:18px 0}.result{padding:14px 0;border-top:1px solid #edf0f2}.complete{margin-top:16px}</style>
